components.css:
.ds-switch{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--rule,#C9C2B0);background:var(--plate,#FCFAF2);direction:rtl}
.ds-switch button{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:64px;padding:10px 16px;border:0;border-inline-end:1px solid var(--rule,#C9C2B0);background:transparent;color:var(--ink,#13241D);text-align:start;cursor:pointer}
.ds-switch button:last-child{border-inline-end:0}
.ds-switch button.active{background:var(--pine,#0B4C3A);color:var(--chalk,#F7F3E6)}
.ds-switch .name{display:flex;flex-direction:column;gap:2px;font:600 14px/1.4 'Readex Pro','Changa',Tahoma,Arial,sans-serif}
.ds-switch .meta{font:400 12px/1.6 'Readex Pro','Changa',Tahoma,Arial,sans-serif;color:var(--muted,#55655B)}
.ds-switch .active .meta{color:#E4EEE0}
.ds-switch .time{font:600 24px/1 'Changa','Readex Pro',Tahoma,Arial,sans-serif;direction:ltr;font-variant-numeric:tabular-nums}
.ds-switch button:focus-visible{outline:2px solid var(--signal-orange,#A54E0F);outline-offset:-4px}

.ds-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));max-width:560px;margin-top:10px;padding-bottom:10px;border-top:1px solid var(--ink,#13241D);border-bottom:1px solid var(--rule-soft,#DDD7C8);direction:rtl}
.ds-fact{position:relative;min-width:0;padding:16px 12px 4px;border-inline-start:1px solid var(--rule-soft,#DDD7C8)}
.ds-fact:first-child{border-inline-start:0;padding-inline-start:0}
.ds-fact:last-child{padding-inline-end:0}
.ds-node{position:absolute;top:-5px;inset-inline-start:12px;width:9px;height:9px;background:var(--pine,#0B4C3A);box-shadow:0 0 0 2px var(--plate,#FCFAF2)}
.ds-fact:first-child .ds-node{inset-inline-start:0}
.ds-node.modelled{background:linear-gradient(90deg,var(--pine,#0B4C3A) 50%,var(--plate,#FCFAF2) 50%);border:1px solid var(--pine,#0B4C3A)}
.ds-node.estimate{background:var(--signal-orange,#A54E0F)}
.ds-label{font:500 12px/1.6 'Readex Pro','Changa',Tahoma,Arial,sans-serif;color:var(--muted,#55655B);margin:0 0 5px}
.ds-value{font:600 30px/1.15 'Changa','Readex Pro',Tahoma,Arial,sans-serif;letter-spacing:-.015em;color:var(--ink,#13241D);font-variant-numeric:tabular-nums;margin:0}
.ds-unit{font:500 12px/1.6 'Readex Pro','Changa',Tahoma,Arial,sans-serif;color:var(--muted,#55655B);margin-inline-start:4px}
.ds-source{font:400 12px/1.6 'Readex Pro','Changa',Tahoma,Arial,sans-serif;color:var(--muted,#55655B);margin:6px 0 0}
.ds-source.estimate{color:var(--signal-orange,#A54E0F)}

.ds-stoprow{display:grid;grid-template-columns:30px minmax(0,1fr) auto 44px;align-items:center;gap:10px;width:100%;min-height:56px;padding:9px 2px;border:0;border-bottom:1px solid var(--rule-soft,#DDD7C8);background:transparent;color:var(--ink,#13241D);text-align:start;cursor:pointer;direction:rtl;font:400 13px/1.6 'Readex Pro','Changa',Tahoma,Arial,sans-serif}
.ds-stoprow:hover{background:var(--plate-2,#F4F0E3)}
.ds-stoprow.selected{background:var(--pine-soft,#E4EBE2)}
.ds-stopnum{width:30px;height:30px;display:grid;place-items:center;border:1px solid var(--rule,#C9C2B0);background:var(--plate,#FCFAF2);font:600 12px/1 'Changa','Readex Pro',Tahoma,Arial,sans-serif;font-variant-numeric:tabular-nums;direction:ltr}
.ds-stoprow.selected .ds-stopnum{background:var(--pine,#0B4C3A);border-color:var(--pine,#0B4C3A);color:var(--chalk,#F7F3E6)}
.ds-stopname{min-width:0}
.ds-stoptime{font:600 14.5px/1.4 'Changa','Readex Pro',Tahoma,Arial,sans-serif;color:var(--ink-2,#33463C);font-variant-numeric:tabular-nums;white-space:nowrap;direction:ltr}
.ds-stoptime.est{color:var(--signal-orange,#A54E0F)}
.ds-stopmark{width:44px;height:44px;display:grid;place-items:center;border:1px solid var(--rule,#C9C2B0);color:var(--ink-2,#33463C);background:var(--plate,#FCFAF2)}
.ds-stopmark svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.ds-stoprow:focus-visible{outline:2px solid var(--signal-orange,#A54E0F);outline-offset:-3px}

.ds-sheet{max-width:560px;background:var(--plate,#FCFAF2);border:1px solid var(--rule,#C9C2B0);box-shadow:0 30px 80px -30px #00000080;direction:rtl}
.ds-sheethead{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 18px;border-bottom:1px solid var(--rule,#C9C2B0);position:sticky;top:0;background:var(--plate,#FCFAF2)}
.ds-sheethead h2{font:600 18px/1.5 'Changa','Readex Pro',Tahoma,Arial,sans-serif;letter-spacing:-.01em;color:var(--ink,#13241D);margin:0}
.ds-sheetclose{width:44px;height:44px;display:grid;place-items:center;border:1px solid transparent;background:transparent;color:var(--ink-2,#33463C);font:400 24px/1 'Readex Pro',Tahoma,Arial,sans-serif;cursor:pointer}
.ds-sheetclose:hover{border-color:var(--rule,#C9C2B0);background:var(--plate-2,#F4F0E3)}
.ds-sheetclose:focus-visible{outline:2px solid var(--signal-orange,#A54E0F);outline-offset:3px}
.ds-sheetbody{padding:18px;font:400 13.5px/1.9 'Readex Pro','Changa',Tahoma,Arial,sans-serif;color:var(--ink-2,#33463C)}
.ds-sheetbody p{margin:0 0 12px}
